"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[14632],{9171:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>c,contentTitle:()=>a,default:()=>l,frontMatter:()=>s,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"type":"mdx","permalink":"/dfg","source":"@site/src/pages/dfg.md","title":"DFG","description":"Detailed project description of the Sciebo RDS project","frontMatter":{"title":"DFG","description":"Detailed project description of the Sciebo RDS project","hide_table_of_contents":true},"unlisted":false}');var i=o(74848),r=o(28453);const s={title:"DFG",description:"Detailed project description of the Sciebo RDS project",hide_table_of_contents:!0},a="Are you looking for a more detailed project description in the context of the DFG-funded project idea?",c={},d=[{value:"Read this!",id:"read-this",level:2}];function h(e){const t={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"are-you-looking-for-a-more-detailed-project-description-in-the-context-of-the-dfg-funded-project-idea",children:"Are you looking for a more detailed project description in the context of the DFG-funded project idea?"})}),"\n",(0,i.jsx)(t.h2,{id:"read-this",children:"Read this!"}),"\n",(0,i.jsx)(t.p,{children:"Against the backdrop of increasing digitization in research, the importance of structured research data management (RDM) cannot be overstated. A recent assessment of the status quo of RDM in North Rhine-Westphalia shows that there are still major gaps when it comes to professional RDM in line with the recommendations of the German Research Foundation (DFG) (DV-ISA, 2016).\n\xa0"}),"\n",(0,i.jsxs)(t.p,{children:["The aim of the \u201csciebo Research Data Services\u201d project is to develop a low-threshold offering for the management of research data that is clearly designed as a service for scientists. The focus is not on developing entirely new services, but rather on building a management suite for flexible integration and coupling with existing services and systems, as well as the exemplary implementation of end-to-end scientific workflows based on real use cases. The established collaboration service \u201c",(0,i.jsx)(t.a,{href:"https://www.sciebo.de/projekt/index.html",children:"sciebo \u2013 die Campuscloud"}),"\u201d already provides a productive platform that allows services to be shared across locations. Based on sciebo, tools, workflows, and services are to be developed that support researchers in implementing structured research data management."]}),"\n",(0,i.jsx)(t.p,{children:"The core idea is to create bridge functionalities that meet researchers where they already store most of their data during the research process and, building on this, provide them with easy-to-use tools, e.g., for preparing data, publishing it, and seamlessly transferring it to repositories or long-term archives. Among other things, connections to the CLARIN web services for the digital humanities and connectors for the Zenodo and EUDAT projects and for the research data repository of the University of M\xfcnster are planned. This will enable consistent and automated work processes."}),"\n",(0,i.jsxs)(t.p,{children:["The project thus ties in nicely with other existing projects: As part of the Research Data Management Organiser Project ",(0,i.jsx)(t.a,{href:"https://rdmorganiser.github.io/",children:"RDMO"}),", a separately operated web application is being developed that allows the information necessary for sustainable data management to be entered and managed centrally. The developed system makes the DMP available in machine-readable form via API. This is a basic requirement for setting up automated, consistent workflows. It is therefore planned to use the RDMO for the creation of DMPs and for recording project-wide parameters (license information, repository for the delivery of research data, etc.). The sciebo RDS project is the first to consistently use these features, which is why a collaboration was agreed upon. In this respect, we consider the distinctive bridging functionality of sciebo RDS to be an ideal complement to our ongoing activities."]}),"\n",(0,i.jsx)(t.p,{children:"It should be clearly emphasized that the goal is not to develop another repository for research data or additional services in the sense of a virtual research environment. Rather, the widely used scientific tool sciebo is to be used as an entry point for research data management and expanded with functionalities that enable the connection and integration of existing repositories and services. The bridging function between the established working environment of scientists and the information infrastructures required for the exchange, archiving, and publication of research data is absolutely paramount in terms of consistent work processes."})]})}function l(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453:(e,t,o)=>{o.d(t,{R:()=>s,x:()=>a});var n=o(96540);const i={},r=n.createContext(i);function s(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);